  "marketing.about.title": { en: "About SoundBloom", ru: "О SoundBloom", kk: "SoundBloom туралы" },
  "marketing.about.mission": { en: "Our Mission", ru: "Наша миссия", kk: "Біздің миссия" },
  "marketing.about.why": { en: "Why SoundBloom", ru: "Почему SoundBloom", kk: "Неге SoundBloom" },
  "marketing.about.experience": { en: "Experience Music Differently", ru: "Слушай музыку по-новому", kk: "Музыканы басқаша сез" },
  "marketing.about.tagline": { en: "Built for the way you actually listen.", ru: "Создано для того, как ты реально слушаешь.", kk: "Шын мәнінде тыңдайтыныңдай жасалған." },
  "marketing.about.hero": { en: "An immersive music experience, built for listeners who stay.", ru: "Погружение в музыку для тех, кто остаётся слушать.", kk: "Тыңдаушылар үшін жасалған терең музыкалық тәжірибе." },
  "marketing.about.p1": { en: "SoundBloom is a premium dark music platform where atmosphere meets access — stream freely, explore deeply, and feel every track in a space designed like a late-night studio session.", ru: "SoundBloom — премиальная тёмная музыкальная платформа, где атмосфера встречается с доступом: слушай свободно, исследуй глубоко и чувствуй каждый трек.", kk: "SoundBloom — атмосфера мен қолжетімділік біріктірілген премиум платформа: еркін тыңда, терең зертте, әр тректі сез." },
  "marketing.about.p2": { en: "We combine open music APIs with a modern web interface so you can discover trending tracks, explore genres, build mood playlists, and listen without leaving the flow of the app.", ru: "Мы объединяем открытые музыкальные API с современным интерфейсом — открывай тренды, жанры, плейлисты и слушай без выхода из приложения.", kk: "Ашық музыка API мен заманауи интерфейсті біріктіреміз — трендтер, жанрлар, плейлисттер, үздіксіз тыңдау." },
  "marketing.about.statListeners": { en: "Active listeners", ru: "Активных слушателей", kk: "Белсенді тыңдаушылар" },
  "marketing.about.statPlaylists": { en: "Curated playlists", ru: "Плейлистов", kk: "Плейлисттер" },
  "marketing.about.statHours": { en: "Hours streamed monthly", ru: "Часов в месяц", kk: "Айлық сағаттар" },
  "marketing.about.missionText": { en: "SoundBloom exists to make discovery feel personal again — a place where every session sounds intentional, not algorithmic noise.", ru: "SoundBloom возвращает личное открытие музыки — каждая сессия звучит осмысленно, а не как шум алгоритмов.", kk: "SoundBloom музыканы жеке ашу сезімін қайтарады — әр сессия мәнді, алгоритмдік шу емес." },
  "marketing.about.whyText": { en: "We blend Jamendo's independent catalog with a cinematic interface built for deep listening, not endless scrolling.", ru: "Jamendo-каталог и кинематографичный интерфейс для глубокого прослушивания, а не бесконечной ленты.", kk: "Jamendo каталогы мен терең тыңдауға арналған кинematik интерфейс — шексіз скролл емес." },
  "marketing.about.experienceText": { en: "From mood playlists to genre deep-dives, SoundBloom turns your screen into an ambient stage for sound.", ru: "От mood-плейлистов до погружения в жанры — экран становится сценой для звука.", kk: "Көңіл-күй плейлисттерінен жанрға терең үнуге дейін — экран дыбыс сахнасына айналады." },
  "marketing.about.builtTitle": { en: "Built for the way you actually listen.", ru: "Создано для того, как ты реально слушаешь.", kk: "Шын мәнінде тыңдайтыныңдай жасалған." },
  "marketing.about.builtP1": { en: "No clutter. No generic templates. Just a matte-black canvas, soft glow, and music that fills the room — whether you are discovering new artists on Home or diving into a genre rabbit hole at 2 AM.", ru: "Без лишнего. Матовый чёрный фон, мягкое свечение и музыка, которая заполняет пространство.", kk: "Артық нәрсе жоқ. Матовый қара фон, ж soft жарық және бөлмені толтыратын музыка." },
  "marketing.about.builtP2": { en: "SoundBloom is a full-stack project: accounts, liked songs, and personal playlists powered by our C# backend.", ru: "SoundBloom — full-stack проект: аккаунты, лайки и личные плейлисты на C# бэкенде.", kk: "SoundBloom — толық стек: аккаунттар, лайктар және жеке плейлисттер C# бэкендте." },

