  "marketing.premium.heroDesc": { en: "SoundBloom Premium — no ads, offline downloads, lossless audio, and exclusive mixes in a cinematic listening environment.", ru: "SoundBloom Premium — без рекламы, офлайн, lossless и эксклюзивные миксы.", kk: "SoundBloom Premium — жарнамасыз, офлайн, lossless және эксклюзив микстер." },
  "marketing.premium.upgradeDesc": { en: "Premium unlocks offline downloads, ultra-quality audio, and an ad-free immersive experience — the way SoundBloom was meant to be heard.", ru: "Premium открывает офлайн, ultra-качество и прослушивание без рекламы.", kk: "Premium офлайн, ultra сапа және жарнамасыз тыңдауды ашады." },
  "marketing.premium.planFreeDesc": { en: "Stream and discover with SoundBloom essentials.", ru: "Стрим и открытия с базовыми возможностями SoundBloom.", kk: "SoundBloom негізгі мүмкіндіктерімен тыңда." },
  "marketing.premium.planPremiumDesc": { en: "The full SoundBloom experience — uninterrupted.", ru: "Полный SoundBloom — без прерываний.", kk: "Толық SoundBloom — үзіліссіз." },
  "marketing.premium.planFamilyDesc": { en: "Premium for up to 6 accounts under one roof.", ru: "Premium для 6 аккаунтов в одной подписке.", kk: "Бір подпискада 6 аккаунтқа Premium." },
  "marketing.premium.featureStandard": { en: "Standard audio quality", ru: "Стандартное качество", kk: "Стандарт сапа" },
  "marketing.premium.featureAds": { en: "Ad-supported listening", ru: "С рекламой", kk: "Жарнамамен" },
