  "marketing.contact.error": { en: "Could not send your message. Please try again.", ru: "Не удалось отправить сообщение. Попробуйте снова.", kk: "Хабарлама жіберілмеді. Қайта көріңіз." },
  "marketing.contact.replyHint": { en: "We reply within 24 hours", ru: "Отвечаем в течение 24 часов", kk: "24 сағат ішінде жауап береміз" },
  "marketing.contact.intro": { en: "Questions, feedback, or partnership ideas — send a message and we will get back to you.", ru: "Вопросы, отзывы или идеи — напиши нам, и мы ответим.", kk: "Сұрақтар, пікірлер немесе әріптестік — хабарлама жібер, жауап береміз." },
  "marketing.contact.discord": { en: "Discord", ru: "Discord", kk: "Discord" },
