function escapeSql(str) {
  return str.replace(/'/g, "''");
}

function namespaceFromKey(key) {
  return key.split(".")[0];
}

const lines = [
  "create table if not exists public.translations (",
  "  id uuid primary key default gen_random_uuid(),",
  "  translation_key text not null,",
  "  locale text not null check (locale in ('en', 'ru', 'kk')),",
  "  value text not null,",
  "  namespace text not null default 'common',",
  "  created_at timestamptz not null default now(),",
  "  unique (translation_key, locale)",
  ");",
  "",
  "create index if not exists translations_locale_idx on public.translations (locale);",
  "create index if not exists translations_key_idx on public.translations (translation_key);",
  "",
  "alter table public.translations enable row level security;",
  "",
"insert into public.translations (translation_key, locale, value, namespace) values",
];

const rows = [];
for (const [key, locales] of Object.entries(T)) {
  const ns = namespaceFromKey(key);
  for (const locale of ["en", "ru", "kk"]) {
    rows.push(
      `  ('${escapeSql(key)}', '${locale}', '${escapeSql(locales[locale])}', '${escapeSql(ns)}')`
    );
  }
}

lines.push(rows.join(",\n"));
lines.push("on conflict (translation_key, locale) do update set");
lines.push("  value = excluded.value,");
lines.push("  namespace = excluded.namespace;");

const outPath = join(__dirname, "..", "sql", "create_translations.sql");
writeFileSync(outPath, lines.join("\n") + "\n", "utf8");
console.log(`Generated ${Object.keys(T).length} keys × 3 locales = ${rows.length} rows`);
console.log(`Written to ${outPath}`);

const bundled = { en: {}, ru: {}, kk: {} };
for (const [key, locales] of Object.entries(T)) {
  for (const locale of ["en", "ru", "kk"]) {
    bundled[locale][key] = locales[locale];
  }
}

const bundledPath = join(
  __dirname,
  "..",
  "..",
  "frontend",
  "src",
  "i18n",
  "bundledTranslations.js"
);
const bundledContent = `export const BUNDLED_TRANSLATIONS = ${JSON.stringify(bundled, null, 2)};
`;
writeFileSync(bundledPath, bundledContent, "utf8");
console.log(`Written bundled fallbacks to ${bundledPath}`);
